(x, y, t) => {
  const cx = 240, cy = 120;
  const warp1 = Math.sin(x*0.008+t*0.2)*30 + Math.cos(y*0.012-t*0.15)*25;
  const warp2 = Math.cos(x*0.01-t*0.18)*20 + Math.sin(y*0.009+t*0.22)*22;
  const warp3 = Math.sin((x+y)*0.007+t*0.12)*15;
  const sx = x + warp1 + warp3*0.5, sy = y + warp2 + warp3*0.5;
  const src = [
    [120+Math.sin(t*0.5)*90, 70+Math.cos(t*0.35)*45, 0.075, 2.1, 0.9],
    [360+Math.cos(t*0.45)*80, 90+Math.sin(t*0.55)*55, 0.065, 1.8, 1.1],
    [240+Math.sin(t*0.3+2)*130, 120+Math.cos(t*0.4+1)*80, 0.055, 2.4, 0.8],
    [80+Math.cos(t*0.7+1)*70, 190+Math.sin(t*0.5+3)*50, 0.09, 1.6, 1.2],
    [400+Math.sin(t*0.35+4)*85, 170+Math.cos(t*0.8+2)*65, 0.07, 2.0, 0.7],
    [200+Math.cos(t*0.4+5)*100, 210+Math.sin(t*0.45)*70, 0.08, 1.9, 1.0],
    [300+Math.sin(t*0.25+3)*110, 40+Math.cos(t*0.6+4)*55, 0.06, 2.5, 0.85],
    [60+Math.cos(t*0.55+2)*60, 130+Math.sin(t*0.4+5)*40, 0.1, 1.4, 1.15]
  ];
  let aS=0, iS=0, cS=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wave=Math.sin(d*f-t*sp);
    aS+=wave*w; iS+=Math.sin(d*f*0.65+t*sp*0.5+1.8)*w;
    cS+=Math.sin(d*f*1.3-t*sp*0.8+2.5)*w*0.4;
  }
  const aN=aS/7.2, iN=iS/7.2, cN=cS/7.2;
  const bg1=Math.sin(sx*0.035+sy*0.02+t*0.7)+Math.sin(sx*0.025-sy*0.035+t*0.95);
  const bg2=Math.sin((sx+sy)*0.1+t*2.2)*0.25+Math.sin((sx-sy)*0.08-t*1.8)*0.25;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const sp1=Math.sin(dist*0.045-ang*3.5-t*1.3)+Math.sin(dist*0.035+ang*4.5-t*1.0);
  const sp2=Math.sin(dist*0.06-ang*2-t*1.8)*0.4;
  const turb=Math.sin(sx*0.08+t*1.5)*Math.cos(sy*0.07-t*1.2)*0.3;
  const react=Math.tanh((aN-iN*0.6+bg1*0.2+bg2+sp1*0.3+sp2+turb+cN*0.15)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.13)*Math.sin(sy*0.13)+Math.sin((sx+sy)*0.09+t)*0.4+Math.sin(sx*0.07-t*0.5)*Math.cos(sy*0.08+t*0.4)*0.3)*1.6)*0.25;
  const micro=Math.sin(sx*0.25+sy*0.18+t*3)*Math.cos(sx*0.15-sy*0.22-t*2.5)*0.08;
  const blend=react*0.65+cell*0.25+micro, v=blend*0.5+0.5;
  const dReact=Math.abs(react);
  const glow=dReact>0.6?(dReact-0.6)*2.5:0;
  const pal=[
    [12,22,82],[18,55,125],[22,95,140],[28,140,135],[75,165,110],
    [180,175,70],[210,135,60],[195,80,65],[150,45,75],[90,25,65],[12,22,82]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.85+Math.sin(react*Math.PI)*0.15+glow*0.2;
  const satBoost=1.0+glow*0.3;
  const edge=dReact>0.72?1.12:1.0;
  const total=lum*satBoost*edge;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f+glow*30)*total)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f+glow*20)*total)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f+glow*40)*total)|0
  ];
}
